-- DocuMind baseline schema.
-- Portable SQL (PostgreSQL production, H2 local development).
-- UUID primary keys are generated by the application layer.

create table roles (
    id          smallint     not null primary key,
    name        varchar(32)  not null,
    created_at  timestamp with time zone not null,
    updated_at  timestamp with time zone not null,
    constraint uk_roles_name unique (name)
);

create table users (
    id             uuid          not null primary key,
    email          varchar(255)  not null,
    password_hash  varchar(100)  not null,
    full_name      varchar(120)  not null,
    job_title      varchar(120),
    global_role_id smallint      not null,
    enabled        boolean       not null,
    last_login_at  timestamp with time zone,
    created_at     timestamp with time zone not null,
    updated_at     timestamp with time zone not null,
    constraint uk_users_email unique (email),
    constraint fk_users_role foreign key (global_role_id) references roles (id)
);

create table workspaces (
    id                   uuid         not null primary key,
    name                 varchar(120) not null,
    slug                 varchar(140) not null,
    owner_id             uuid         not null,
    storage_provider     varchar(20)  not null,
    max_upload_size_mb   integer      not null,
    notify_on_upload     boolean      not null,
    notify_on_validation boolean      not null,
    created_by           uuid,
    created_at           timestamp with time zone not null,
    updated_at           timestamp with time zone not null,
    constraint uk_workspaces_slug unique (slug),
    constraint fk_workspaces_owner foreign key (owner_id) references users (id)
);

create table workspace_members (
    id           uuid     not null primary key,
    workspace_id uuid     not null,
    user_id      uuid     not null,
    role_id      smallint not null,
    created_by   uuid,
    created_at   timestamp with time zone not null,
    updated_at   timestamp with time zone not null,
    constraint uk_workspace_members unique (workspace_id, user_id),
    constraint fk_members_workspace foreign key (workspace_id) references workspaces (id) on delete cascade,
    constraint fk_members_user foreign key (user_id) references users (id) on delete cascade,
    constraint fk_members_role foreign key (role_id) references roles (id)
);
create index idx_members_user on workspace_members (user_id);

create table document_templates (
    id           uuid          not null primary key,
    workspace_id uuid          not null,
    name         varchar(140)  not null,
    category     varchar(40)   not null,
    description  varchar(1000),
    active       boolean       not null,
    created_by   uuid,
    created_at   timestamp with time zone not null,
    updated_at   timestamp with time zone not null,
    constraint uk_templates_workspace_name unique (workspace_id, name),
    constraint fk_templates_workspace foreign key (workspace_id) references workspaces (id) on delete cascade
);

create table template_fields (
    id            uuid         not null primary key,
    workspace_id  uuid         not null,
    template_id   uuid         not null,
    name          varchar(80)  not null,
    label         varchar(140) not null,
    data_type     varchar(20)  not null,
    required      boolean      not null,
    display_order integer      not null,
    created_at    timestamp with time zone not null,
    updated_at    timestamp with time zone not null,
    constraint fk_template_fields_template foreign key (template_id) references document_templates (id) on delete cascade
);
create index idx_template_fields_template on template_fields (template_id);

create table documents (
    id                uuid          not null primary key,
    workspace_id      uuid          not null,
    file_name         varchar(255)  not null,
    title             varchar(255),
    description       varchar(1000),
    content_type      varchar(120)  not null,
    size_bytes        bigint        not null,
    pages             integer       not null,
    checksum          varchar(64),
    category          varchar(40)   not null,
    status            varchar(20)   not null,
    progress          integer       not null,
    validation_status varchar(20)   not null,
    template_id       uuid,
    current_version   integer       not null,
    uploaded_by       uuid,
    deleted_at        timestamp with time zone,
    created_by        uuid,
    created_at        timestamp with time zone not null,
    updated_at        timestamp with time zone not null,
    constraint fk_documents_workspace foreign key (workspace_id) references workspaces (id) on delete cascade,
    constraint fk_documents_template foreign key (template_id) references document_templates (id) on delete set null,
    constraint fk_documents_uploader foreign key (uploaded_by) references users (id)
);
create index idx_documents_workspace on documents (workspace_id);
create index idx_documents_status on documents (workspace_id, status);
create index idx_documents_category on documents (workspace_id, category);
create index idx_documents_uploaded_at on documents (workspace_id, created_at);

create table document_versions (
    id               uuid         not null primary key,
    workspace_id     uuid         not null,
    document_id      uuid         not null,
    version_number   integer      not null,
    file_name        varchar(255) not null,
    content_type     varchar(120) not null,
    size_bytes       bigint       not null,
    checksum         varchar(64),
    storage_key      varchar(512) not null,
    storage_provider varchar(20)  not null,
    uploaded_by      uuid,
    created_at       timestamp with time zone not null,
    updated_at       timestamp with time zone not null,
    constraint uk_document_versions unique (document_id, version_number),
    constraint fk_versions_document foreign key (document_id) references documents (id) on delete cascade
);
create index idx_versions_workspace on document_versions (workspace_id);

create table processing_jobs (
    id            uuid          not null primary key,
    workspace_id  uuid          not null,
    document_id   uuid          not null,
    status        varchar(20)   not null,
    progress      integer       not null,
    attempt       integer       not null,
    started_at    timestamp with time zone,
    finished_at   timestamp with time zone,
    error_message varchar(2000),
    worker        varchar(80),
    created_by    uuid,
    created_at    timestamp with time zone not null,
    updated_at    timestamp with time zone not null,
    constraint fk_jobs_document foreign key (document_id) references documents (id) on delete cascade
);
create index idx_jobs_workspace_status on processing_jobs (workspace_id, status);
create index idx_jobs_document on processing_jobs (document_id);

create table extracted_fields (
    id                uuid          not null primary key,
    workspace_id      uuid          not null,
    document_id       uuid          not null,
    template_field_id uuid,
    field_name        varchar(80)   not null,
    field_label       varchar(140)  not null,
    data_type         varchar(20)   not null,
    field_value       varchar(2000),
    original_value    varchar(2000),
    confidence        numeric(5, 2),
    source_page       integer,
    status            varchar(20)   not null,
    edited_by         uuid,
    edited_at         timestamp with time zone,
    created_by        uuid,
    created_at        timestamp with time zone not null,
    updated_at        timestamp with time zone not null,
    constraint uk_extracted_fields unique (document_id, field_name),
    constraint fk_fields_document foreign key (document_id) references documents (id) on delete cascade,
    constraint fk_fields_template_field foreign key (template_field_id) references template_fields (id) on delete set null
);
create index idx_extracted_fields_workspace on extracted_fields (workspace_id, document_id);

create table document_validations (
    id               uuid          not null primary key,
    workspace_id     uuid          not null,
    document_id      uuid          not null,
    document_version integer       not null,
    status           varchar(20)   not null,
    submitted_by     uuid,
    submitted_at     timestamp with time zone,
    decided_by       uuid,
    decided_at       timestamp with time zone,
    decision_comment varchar(2000),
    created_by       uuid,
    created_at       timestamp with time zone not null,
    updated_at       timestamp with time zone not null,
    constraint fk_validations_document foreign key (document_id) references documents (id) on delete cascade
);
create index idx_validations_workspace_status on document_validations (workspace_id, status);
create index idx_validations_document on document_validations (document_id);

create table validation_comments (
    id            uuid          not null primary key,
    workspace_id  uuid          not null,
    validation_id uuid          not null,
    author_id     uuid,
    author_name   varchar(120)  not null,
    message       varchar(2000) not null,
    created_at    timestamp with time zone not null,
    updated_at    timestamp with time zone not null,
    constraint fk_comments_validation foreign key (validation_id) references document_validations (id) on delete cascade
);
create index idx_comments_validation on validation_comments (validation_id);

create table audit_logs (
    id           uuid          not null primary key,
    workspace_id uuid,
    actor_id     uuid,
    actor_email  varchar(255),
    action       varchar(60)   not null,
    entity_type  varchar(60)   not null,
    entity_id    uuid,
    details      varchar(2000),
    ip_address   varchar(64),
    created_at   timestamp with time zone not null,
    updated_at   timestamp with time zone not null
);
create index idx_audit_workspace on audit_logs (workspace_id, created_at);
create index idx_audit_entity on audit_logs (entity_type, entity_id);

create table refresh_tokens (
    id          uuid        not null primary key,
    user_id     uuid        not null,
    token_hash  varchar(64) not null,
    expires_at  timestamp with time zone not null,
    revoked_at  timestamp with time zone,
    created_by  uuid,
    created_at  timestamp with time zone not null,
    updated_at  timestamp with time zone not null,
    constraint uk_refresh_tokens_hash unique (token_hash),
    constraint fk_refresh_tokens_user foreign key (user_id) references users (id) on delete cascade
);
create index idx_refresh_tokens_user on refresh_tokens (user_id);

insert into roles (id, name, created_at, updated_at) values
    (1, 'SUPER_ADMIN', current_timestamp, current_timestamp),
    (2, 'ADMIN',       current_timestamp, current_timestamp),
